<?php session_start();require_once __DIR__.'/../../conn.php';require_once __DIR__.'/../../auth.php';requireStaff();$msg='';$mt='';if($_SERVER['REQUEST_METHOD']==='POST'){$fid=(int)$_POST['furniture_id'];if(isset($_POST['delete'])){$chk=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) as cnt FROM Orders WHERE furniture_id=$fid"))['cnt'];if($chk>0){$msg="Cannot delete: {$chk} order(s) exist.";$mt='error';}else{mysqli_query($conn,"DELETE FROM Furniture_Material WHERE furniture_id=$fid");mysqli_query($conn,"DELETE FROM Furniture WHERE furniture_id=$fid");$msg='Furniture deleted.';$mt='success';}}elseif(isset($_POST['update'])){$n=trim($_POST['furniture_name']);$d=trim(isset($_POST['description'])?$_POST['description']:'');$p=(float)$_POST['price'];$s=(int)$_POST['stock_quantity'];$st=mysqli_prepare($conn,"UPDATE Furniture SET furniture_name=?,description=?,price=?,stock_quantity=? WHERE furniture_id=?");mysqli_stmt_bind_param($st,'ssdii',$n,$d,$p,$s,$fid);if(mysqli_stmt_execute($st)){$msg='Furniture updated.';$mt='success';}else{$msg='Update failed.';$mt='error';}mysqli_stmt_close($st);}}$r=mysqli_query($conn,"SELECT * FROM Furniture ORDER BY furniture_id");$rs=array();while($rw=mysqli_fetch_assoc($r))$rs[]=$rw;mysqli_free_result($r);$oc=array();$or=mysqli_query($conn,"SELECT furniture_id,COUNT(*) as cnt FROM Orders GROUP BY furniture_id");while($ow=mysqli_fetch_assoc($or))$oc[$ow['furniture_id']]=$ow['cnt'];mysqli_close($conn);?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Manage Furniture</title><link rel="stylesheet" href="../style.css"><style>.mc{padding:24px 32px}.tw{background:#fff;border-radius:20px;padding:20px;overflow-x:auto;box-shadow:0 1px 3px rgba(0,0,0,.06)}.m{padding:12px 16px;border-radius:10px;margin-bottom:16px;font-weight:500;font-size:.9rem}.me{background:#fef2f2;color:#991b1b;border:1px solid #fecaca}.ms{background:#f0fdf4;color:#166534;border:1px solid #bbf7d0}table{width:100%;border-collapse:collapse}th,td{padding:10px 12px;border-bottom:1px solid #e0e0e0;text-align:left}th{font-weight:500;color:#5f6368;font-size:13px}.is{padding:6px 8px;border-radius:6px;border:1px solid #dadce0;font-size:12px;width:90px}.iw{width:120px}.id{width:100px}.bs{padding:6px 12px;border-radius:16px;font-size:12px;font-weight:500;cursor:pointer;border:none;color:#fff;background:#1a73e8}.bs:hover{background:#1557b0}.bd{background:#d93025}.bd:hover{background:#b3261e}.bs:disabled{background:#9aa0a6;cursor:not-allowed}.thumb{width:80px;height:45px;object-fit:contain;border-radius:6px;border:1px solid #e0e0e0;background:#fafafa;vertical-align:middle}</style></head><body><div id="sidebar-container"></div><div class="mc"><div class="top-bar"><div class="page-title">Manage Furniture</div></div><div class="content-container"><?php if($msg):?><div class="m m<?php echo $mt[0];?>"><?php echo htmlspecialchars($msg);?></div><?php endif;?><div class="tw"><table><thead><tr><th>Img</th><th>ID</th><th>Name</th><th>Desc</th><th>Price</th><th>Stock</th><th>Orders</th><th>Edit</th><th>Delete</th></tr></thead><tbody><?php foreach($rs as $rw):$fid=$rw['furniture_id'];$cnt=isset($oc[$fid])?$oc[$fid]:0;?><tr><form method="post"><input type="hidden" name="furniture_id" value="<?php echo $fid;?>"><td><img src="/image.php?fid=<?php echo $fid;?>" class="thumb" alt=""></td><td><?php echo $fid;?></td><td><input type="text" name="furniture_name" value="<?php echo htmlspecialchars($rw['furniture_name']);?>" class="is iw" required></td><td><input type="text" name="description" value="<?php echo htmlspecialchars(isset($rw['description'])?$rw['description']:'');?>" class="is id"></td><td><input type="number" name="price" value="<?php echo $rw['price'];?>" step="0.01" class="is" required></td><td><input type="number" name="stock_quantity" value="<?php echo $rw['stock_quantity'];?>" class="is" required></td><td><?php echo $cnt;?></td><td><button type="submit" name="update" value="1" class="bs">Save</button></td><td><button type="submit" name="delete" value="1" class="bs bd" <?php echo $cnt>0?'disabled':'';?> onclick="return confirm('Delete this furniture?');">Del</button></td></form></tr><?php endforeach;?></tbody></table></div></div></div><script src="../sidebar.js"></script><script>loadSidebar('manage-furniture');</script></body></html>
